import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        int cnt = 0;

        String gk = s.replace("at", "@");
        gk = gk.replace("dot", ".");
        // System.out.println(gk);
        int n = gk.length();
        char[] k = gk.toCharArray();

        if (k[0] == '.') {
            k[0] = 'd'; // Temporarily assign 'dot' logic with 'd' as placeholder
        }
        if (k[n - 1] == '.') {
            k[n - 1] = 'd';
        }
        if (k[0] == '@') {
            k[0] = 'a'; // Temporarily assign 'at' logic with 'a' as placeholder
        }
        if (k[n - 1] == '@') {
            k[n - 1] = 'a';
        }

        for (int x = 0; x < k.length; x++) {
            if (k[x] == '@' && cnt == 0) {
                cnt = 1;
            } else if (k[x] == '@') {
                k[x] = 'a'; // Change subsequent '@' to 'at'
            }
            System.out.print(k[x]);
        }
    }
}
